    },
    {
      "dsl": "unsettled(direction(\"months_at_address\"))",
      "sentence_id": 4
    },
    {
      "dsl": "interaction(\"utilization\", \"n_delinquencies\", pattern=\"amplification\")",
      "sentence_id": 5
    },
    {
      "dsl": "strength(\"utilization & n_delinquencies\") == \"strong\"",
      "sentence_id": 5
    },
    {
      "dsl": "negligible(\"num_dependents\")",
      "sentence_id": 6
    }
  ],
  "sentences": [
    {
      "id": 1,
      "text": "Revolving credit utilization is the most important driver of default risk, and risk increases as utilization rises."
    },
    {
      "id": 2,
      "text": "The number of past delinquencies is the second most important driver, and risk increases when an applicant has any delinquencies."
    },
    {
      "id": 3,
      "text": "Risk decreases with higher annual income and longer credit history."
    },
    {
      "id": 4,
      "text": "The data do not settle whether debt-to-income ratio, recent inquiries, age, number of dependents, or time at the current address affect risk."
    },
    {
      "id": 5,
      "text": "The effect of utilization on risk grows with the number of delinquencies, and this interaction is a strong driver."
    },
    {
      "id": 6,
      "text": "The number of dependents hardly matters."
    }
  ]
}

